def is_woodall(x): 
    if (x % 2 == 0): 
        return False
    if (x == 1): 
        return True
    n = 1
    while (n * (2 ** n) - 1 <= x):
        if (n * (2 ** n) - 1 == x):
            return True
        n += 1
    return False

